{
  "type": "mcp-server",
  "packageName": "@mtane0412/perspective-mcp-server",
  "description": "Integrates with Perspective API to analyze text toxicity and provide content moderation across multiple languages for enhanced online safety.",
  "url": "https://github.com/mtane0412/perspective-mcp-server",
  "runtime": "node",
  "license": "unknown",
  "env": {
    "PERSPECTIVE_API_KEY": {
      "description": "your-api-key",
      "required": true
    }
  },
  "name": "Perspective MCP Server"
}

{
  "type": "mcp-server",
  "packageName": "mcp-cisco-support",
  "description": "A production-ready TypeScript MCP (Model Context Protocol) server for Cisco Support APIs with comprehensive security and dual transport support. This extensible server provides access to multiple Cisco Support APIs including Bug Search, Case Management, and End-of-Life information.",
  "url": "https://github.com/sieteunoseis/mcp-cisco-support",
  "runtime": "node",
  "license": "mit",
  "env": {
    "PORT": {
      "description": "Server port for HTTP mode",
      "required": true
    },
    "NODE_ENV": {
      "description": "Node environment (development/production)",
      "required": true
    },
    "SUPPORT_API": {
      "description": "Enable specific Cisco Support APIs (comma-separated list)",
      "required": true
    },
    "CISCO_CLIENT_ID": {
      "description": "Your Cisco API Client ID for OAuth2 authentication",
      "required": true
    },
    "MCP_BEARER_TOKEN": {
      "description": "Custom Bearer token for HTTP authentication (HTTP mode only)",
      "required": true
    },
    "CISCO_CLIENT_SECRET": {
      "description": "Your Cisco API Client Secret for OAuth2 authentication",
      "required": true
    },
    "DANGEROUSLY_OMIT_AUTH": {
      "description": "Disables HTTP authentication entirely (development/testing only)",
      "required": true
    }
  },
  "name": "MCP Cisco Support"
}
